changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.muxlisa.enabled', 'true', 'BOOLEAN', 'Master switch for Muxlisa speech-to-text. false = POST /v1/speech/stt is refused without contacting Muxlisa.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.muxlisa.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.muxlisa.base-url', 'https://service.muxlisa.uz', 'STRING', 'Muxlisa base URL. Inactive by default: the deployed value may come from MUXLISA_BASE_URL - confirm before activating.', false, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.muxlisa.base-url');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.muxlisa.stt-endpoint', '/api/v2/stt', 'STRING', 'Muxlisa STT endpoint path.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.muxlisa.stt-endpoint');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.muxlisa.max-audio-size-bytes', '5242880', 'NUMBER', 'Largest accepted recording in bytes (Muxlisa itself caps at 5 MB).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.muxlisa.max-audio-size-bytes');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'http-client.muxlisa.connect-timeout-millis', '3000', 'NUMBER', 'Connect timeout (ms) - Muxlisa client.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'http-client.muxlisa.connect-timeout-millis');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'http-client.muxlisa.read-timeout-millis', '30000', 'NUMBER', 'Read/response timeout (ms) - Muxlisa client; STT time grows with audio length.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'http-client.muxlisa.read-timeout-millis');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'http-client.muxlisa.max-connections', '25', 'NUMBER', 'Total pooled-connection cap - Muxlisa client.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'http-client.muxlisa.max-connections');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'http-client.muxlisa.max-connections-per-route', '5', 'NUMBER', 'Per-route pooled-connection cap - Muxlisa client.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'http-client.muxlisa.max-connections-per-route');
